const datos = $input.first().json;

let respuesta = String(datos.output || "");

// No permitir afirmaciones de verificación
// que todavía no están respaldadas
// por una validación independiente.
respuesta = respuesta.replace(
  /\b(CONFIRMADO|VERIFICADO)\b/gi,
  "POR_VERIFICAR"
);

// Evitar afirmar que todos los resultados
// son oportunidades vigentes.
respuesta = respuesta.replace(
  /(?:3|tres)\s+oportunidades reales y vigentes/gi,
  "3 oportunidades encontradas cuya vigencia debe verificarse"
);

// Advertir sobre referencias antiguas.
if (/\b2025\b/.test(respuesta)) {
  respuesta =
    "AVISO: Esta búsqueda contiene referencias de 2025. No se ha confirmado su vigencia en 2026.\n\n"
    + respuesta;
}

return [{
  json: {
    ...datos,
    output: respuesta
  }
}];
